mapper.select:
select token_id, token_type, ref_id, token, expire_at, used_at, create_time
from gas_dynamic_token
where token_type = #{tokenType} and ref_id = #{refId}
  and used_at is null and expire_at > now() and create_time > #{freshWindow}
order by token_id desc
limit 1

select token_id, token_type, ref_id, token, expire_at, used_at, create_time
from gas_dynamic_token
where token = #{token} and token_type = #{tokenType}
  and used_at is null and expire_at > #{now}
limit 1

mapper.insert:
insert into gas_dynamic_token(
	token_type, ref_id, token, expire_at, create_time
)values(
	#{tokenType}, #{refId}, #{token}, #{expireAt}, sysdate()
)
